// Discovery request, spec §14.3 / §5:
// GET /.well-known/agent-card.json HTTP/1.1
// Example: https://agent.example.com/.well-known/agent-card.json
//
// Per-request extension negotiation header (§14.2.2):
// A2A-Extensions: <uri>[,<uri>...]
//
// WARNING: this sample serializes the security-requirements field as "security",
// but a2a.proto declares `repeated SecurityRequirement security_requirements = 9;`
// with no json_name override (would protojson-encode as "securityRequirements").
// Resolve against a live server before freezing a parser.

// SCHEMA (closed Payment Mandate, vct = "mandate.payment.1")
// Name                | Type              | Req | Description
// vct                 | string            | Yes | SD-JWT Verifiable Credential Type claim
// transaction_id      | string            | Yes | base64url-encoded hash of checkout_jwt; hash alg MUST equal
//                     |                   |     | the sd_hash alg for this SD-JWT, or sha256 if absent
// payee               | Merchant          | Yes | The merchant receiving the payment
// pisp                | Pisp              | No  | Payment Initiation Service Provider
// payment_amount      | Amount            | Yes | { currency: ISO4217 alpha-3, amount: integer minor units }
//                     |                   |     | e.g. 27999 = $279.99. Final value confirmed by the user.
// payment_instrument  | PaymentInstrument | Yes | { id, type, description }; types seen: card, UPI, dpc
// execution_date      | string (ISO8601)  | No  | absent = immediate execution
// risk_data           | object            | No  | risk signals collected by the Trusted Surface at creation
// iat                 | integer           | No  | Unix epoch
// exp                 | integer           | No  | Unix epoch
// The open Payment Mandate (vct "mandate.payment.open.1") MAY include any
// property from the closed one, and carries `constraints[]` + `cnf.jwk`.

// CLOSED PAYMENT MANDATE (typ "kb+sd-jwt"), verbatim from spec:
{
  "issuer_signed_jwt": {
    "header": { "alg": "ES256", "typ": "kb+sd-jwt" },
    "payload": {
      "delegate_payload": [ { "...": "G2DuU6IjyDkD-9ItStdsUo48C5uJqDs1E9Hf5GT3TgM" } ],
      "iat": 1777342370,
      "aud": "credential-provider",
      "nonce": "a8b7c6d5e4f3a2b1c0d9e8f7a6b5c4d3",
      "sd_hash": "uixoHemmfrrCSbPREo9j-ziLuMkqExsPeWrwA-PK0Ck",
      "_sd_alg": "sha-256"
    }
  },
  "disclosures": [
    { "digest": "G2DuU6IjyDkD-9ItStdsUo48C5uJqDs1E9Hf5GT3TgM",
      "decoded": [ "FW6McBJImqODuhQlpI4Idw", {
        "vct": "mandate.payment.1",
        "transaction_id": "NivWhuqfzcvZNapvIEJ2-3tsdQLkiuIcye2g46WVgX8",
        "payee": { "id": "merchant_1", "name": "Demo Merchant", "website": "https://demo-merchant.example" },
        "payment_amount": { "amount": 19900, "currency": "USD" },
        "payment_instrument": { "id": "stub", "type": "card", "description": "Card ••••4242" }
      } ] }
  ]
}

// OPEN PAYMENT MANDATE (user-signed constraint envelope), verbatim:
{
  "vct": "mandate.payment.open.1",
  "constraints": [
    { "type": "payment.amount_range", "currency": "USD", "max": 20000, "min": 0 },
    { "type": "payment.allowed_payees", "allowed": [ { "...": "oEH7i1gyb-zn6awwjy57LvzxkQDfD-8tvlC2XuIkgOA" } ] },
    { "type": "payment.reference", "conditional_transaction_id": "FzLoxbbtgQGYZxoSM2NJYJtkFTSsdfUBoVEQ12k7JN8" }
  ],
  "cnf": { "jwk": { "crv": "P-256", "kty": "EC",
                     "x": "QpSyxPQHy38xckypDr54gZ3T42zj9iLtV4koyb5U27c",
                     "y": "37HLd7JJinxjJIn8J7HijssoeclbfhdW-gUL7feI9lw" } },
  "iat": 1777342357,
  "exp": 1777345957
}

// payment.agent_recurrence  — reuse conditions for an open mandate
{ "type": "payment.agent_recurrence", "frequency": "MONTHLY", "max_occurrences": 12 }
// frequency enum: ON_DEMAND, DAILY, WEEKLY, BIWEEKLY, MONTHLY, QUARTERLY, ANNUALLY
// Evaluation: true iff the current Payment Mandate is sufficiently separated in time
// from the previous presentation to meet `frequency`, and occurrences <= max_occurrences.

// payment.allowed_payees — payee allowlist (selectively disclosable)
{ "type": "payment.allowed_payees",
  "allowed": [ { "name": "Merchant Choice", "website": "https://merchant-choice.com" } ] }
// Evaluation: the `payee` property of the Payment Mandate MUST be present in `allowed`.

// payment.allowed_payment_instruments
{ "type": "payment.allowed_payment_instruments",
  "allowed": [ { "id": "abe3c...", "type": "card", "description": "network ··· 1234" },
               { "id": "zde4d...", "type": "UPI",  "description": "user****@bankname" } ] }

// payment.allowed_pisps
{ "type": "payment.allowed_pisps",
  "allowed": [ { "legal_name": "Example Payment Services Ltd.",
                 "brand_name": "ExamplePay", "domain_name": "examplepay.com" } ] }

// payment.amount_range — per-transaction cap
{ "type": "payment.amount_range", "max": 100.50, "min": 10.00, "currency": "USD" }
// Schema says max/min are "integer ... in minor (cents) unit of currency";
// the published example shows decimals. Treat minor units as canonical.

// payment.budget — cumulative cap, used with agent_recurrence
{ "type": "payment.budget", "max": 1000.00, "currency": "USD" }
// Evaluation (verbatim): "the requested amount plus the total sum of amounts from
// previously closed Payment Mandates MUST be less than or equal to `max`. After
// approval, the amount MUST be added to the accumulated total for future evaluation."
// => the Verifier is REQUIRED to hold spend state. This is where an on-chain
//    accumulator (AiKi) is a genuine architectural contribution.

// payment.reference — chain a Payment Mandate to an open Checkout Mandate
{ "type": "payment.reference", "conditional_transaction_id": "A4wG4B..." }
// Evaluation: the approved order's Checkout Mandate MUST contain an open Checkout
// Mandate with a matching hash in its delegate chain (alg = _sd_alg, else sha-256).

// payment.execution_date
{ "type": "payment.execution_date",
  "not_before": "2026-03-31T00:00:00Z", "not_after": "2026-04-30T23:59:59Z" }

// checkout.allowed_merchants / checkout.line_items (Checkout Mandate side)
{ "type": "checkout.line_items",
  "items": [ { "id": "id-shoe-choices",
               "acceptable_items": [ {"id": "BAB1234", "title": "Red Style"},
                                     {"id": "FAF1234", "title": "Blue Style"} ],
               "quantity": 1 } ] }
// Evaluation is a normative maximal-flow matching between constraint items and
// checkout line items; no item or constraint entry may be used more than once.

// CLOSED CHECKOUT MANDATE SCHEMA (vct = "mandate.checkout.1")
// Name          | Type    | Req | SD? | Description
// vct           | string  | Yes | No  | SD-JWT VC Type claim
// checkout_jwt  | string  | Yes | Yes | base64url-encoded serialized merchant-signed JWT of the Checkout payload
// checkout_hash | string  | Yes | No  | base64url hash of checkout_jwt; alg MUST match _sd_alg, else sha-256
// iat           | integer | No  | No  | Unix epoch
// exp           | integer | No  | No  | Unix epoch
// Open form: vct = "mandate.checkout.open.1", carries constraints[] + cnf.jwk.
// "when used with the Universal Commerce Protocol this MUST be the Checkout object."
// SECURITY: "the Checkout JWT MUST be signed using a digital signature scheme
// (e.g., ECDSA) and not a deterministic signature (e.g., Ed25519)."

// CHECKOUT RECEIPT
// status             ReceiptStatus  Yes  Success | Error
// iss                string         Yes  issuer of the receipt
// iat                integer        Yes  Unix epoch
// reference          string         Yes  hash of the closed Mandate this receipt binds to
// error              string         No   present iff status is Error
// error_description  string         No   present iff status is Error
// order_id           string         No   present iff status is Success

// PAYMENT RECEIPT
// status                   ReceiptStatus  Yes
// iss                      string         Yes
// iat                      integer        Yes
// reference                string         Yes  hash of the closed Mandate
// error / error_description                No
// payment_id               string         Yes
// psp_confirmation_id      string         No   only if Success
// network_confirmation_id  string         No   only if Success

// A2A wire keys used by the AP2 reference implementation:
//   PAYMENT_MANDATE_SD_JWT_KEY  = "ap2.mandates.PaymentMandateSdJwt"
//   CHECKOUT_MANDATE_SD_JWT_KEY = "ap2.mandates.CheckoutMandateSdJwt"
//   PAYMENT_RECEIPT_DATA_KEY    = "ap2.PaymentReceipt"
//   DEFAULT_MANDATE_TTL_SECONDS = 60 * 60

// The Agent constructs an OpenID4VP Authorization Request whose `transaction_data`
// array contains base64url-encoded JSON objects. The mandate delegation object
// MUST contain, before encoding:
//   type                 REQUIRED  MUST be the string "delegate"
//   format               REQUIRED  required VDC format of the returned Mandate
//   delegate_payload     REQUIRED  array of Mandate Content payloads as JSON objects
//   delegate_disclosures OPTIONAL  Selective Disclosures in the delegate_payload
// "the `delegate_payload` MUST be included as part of the Key Binding."

{
  "requests": [{
    "protocol": "openid4vp-v1-unsigned",
    "data": {
      "response_type": "vp_token",
      "response_mode": "dc_api",
      "nonce": "b5d4e074-dff5-4cd5-a506-f09dd6f2e33a",
      "dcql_query": {
        "credentials": [{
          "id": "dpc_credential",
          "format": "dc+sd-jwt",
          "meta": { "vct_values": ["com.emvco.dpc"] },
          "claims": [ {"path": ["card_last_four"]},
                      {"path": ["card_network_code"]},
                      {"path": ["credential_id"]} ]
        }]
      },
      "transaction_data": [ "<base64url payment_card UI object>",
                            "<base64url delegate object>" ],
      "client_metadata": {
        "client_id_scheme": "x509_san_dns",
        "vp_formats": { "dc+sd-jwt": { "sd-jwt_alg_values": ["ES256"],
                                        "kb-jwt_alg_values": ["ES256"] } }
      }
    }
  }]
}

// Decoded transaction_data[1] — the cryptographic mandate binding:
{
  "type": "delegate",
  "format": "dc+sd-jwt",
  "credential_ids": ["dpc_credential"],
  "transaction_data_hashes_alg": ["sha-256"],
  "delegate_payload": [
    { "vct": "mandate.checkout.1",
      "checkout_jwt": "eyJhbGciOiJFUzI1NiIs...<Merchant_Checkout_JWT>",
      "checkout_hash": "3WiKMabE8NRYJgveUbyAZ3pBqRfPrWwGDbOyvbO1eYA",
      "cnf": { "jwk": { "kty": "EC", "crv": "P-256", "use": "sig",
                        "x": "c09-Eo2PvuO6VrfzLAxTZXBa3ZWkBaa0pR2jcOYKlw",
                        "y": "gRETv5wMvNiZJqckokCyDAjIIEg3Y2m77VryMvS75Ww" } } },
    { "vct": "mandate.payment.1",
      "transaction_id": "3WiKMabE8NRYJgveUbyAZ3pBqRfPrWwGDbOyvbO1eYA",
      "payment_amount": { "amount": 15000, "currency": "USD" },
      "payee": { "id": "merchant_1", "name": "Generic Merchant",
                 "website": "https://demo-merchant.example" },
      "payment_instrument": { "id": "b3f1c8a2-6d4e-4f9a-9e3d-8a7c2f1b9d34",
                              "type": "dpc", "description": "DPC ···· 4444" } }
  ]
}

