// Required headers on the A2A binding:
//   UCP-Agent: profile="https://agent.example/profiles/v2025-11/shopping-agent.json"
//   X-A2A-Extensions: https://ucp.dev/{{ ucp_version }}/specification/reference
//   Content-Type: application/json

// AP2 activation rules once dev.ucp.shopping.ap2_mandate is in the capability
// intersection ("Security Locked" — neither party may revert to unprotected checkout):
//   - business MUST include ap2.merchant_authorization in all checkout responses
//   - business MUST NOT accept a complete_checkout request lacking ap2.checkout_mandate
//   - platform MUST verify the business's signature before presenting checkout to the user
//   - all AP2 fields nest under a single top-level `ap2` object, excluded from the
//     business's signature canonicalization

POST /agentic_commerce/delegate_payment      // direction: Agent (OpenAI) -> PSP
Headers: Authorization, Accept-Language, User-Agent, Idempotency-Key,
         Request-Id, Content-Type, Signature, Timestamp, API-Version

// Request body (required unless noted)
{
  "payment_method": { /* PaymentMethodCard */ },   // required
  "allowance":      { /* Allowance */ },           // required
  "billing_address":{ /* Address */ },             // optional
  "risk_signals":   [ /* Risk Signal */ ],         // required
  "metadata":       { }                            // required
}

// Allowance — "Constraints on how the delegated payment method can be used"
{
  "reason": "one_time",            // enum, currently ONLY "one_time"
  "max_amount": 2599,              // integer, minor units
  "currency": "usd",               // ^[a-z]{3}$  lowercase ISO-4217
  "checkout_session_id": "...",
  "merchant_id": "...",            // maxLength 256
  "expires_at": "2026-04-17T12:00:00Z"   // RFC 3339
}

// PaymentMethodCard required fields:
//   type (const "card"), card_number_type ("fpan" | "network_token"),
//   number, display_card_funding_type ("credit"|"debit"|"prepaid"), metadata
// Optional: exp_month, exp_year, name, cvc, cryptogram, eci_value,
//   checks_performed[] ("avs"|"cvv"|"ani"|"auth0"), iin, display_wallet_type,
